import{z as c,x as B,o as E,c as p,q as n,j as l,D as e,d as i,s as r,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"成本函数性质","description":"","frontmatter":{"title":"成本函数性质","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cost-fn-properties.md","filePath":"econ/cost-fn-properties.md","lastUpdated":1791413859000}'),d={name:"econ/cost-fn-properties.md"};function A(w,a,h,m,q,C){const o=B("Mermaid");return E(),p("div",null,[a[2]||(a[2]=n('<h1 id="成本函数性质" tabindex="-1">成本函数性质 <a class="header-anchor" href="#成本函数性质" aria-label="Permalink to &quot;成本函数性质&quot;">​</a></h1><div class="epigraph"><p>成本是投入需求集的支撑函数：对要素价格一次齐次、非降、凹；这些在包络引理之前就已经从线性目标推出来。</p><footer>—— 据 Varian, Microeconomic Analysis；McFadden, Duality of Production, 1978 整理</footer></div><p><a href="/econ/cost-minimization">上一课</a>（成本最小化）。定义了 \\(c(w,q)=\\min_z w\\cdot z\\) s.t. \\(f(z)\\ge q\\)，并在边注里点过齐次、凹与 Shephard。本课不重解那道规划，也不把 TRS \\(=w\\) 比再写一遍。缺口是把值函数的性质收成定理：<strong>在对 \\(w\\) 求导读出 \\(z\\) 之前，\\(c\\) 已经必须满足哪些等式与不等式。</strong> 下一课才把包络升级成引理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(c\\) 是最优值，不是又一个任意的会计科目。任意光滑函数不能当成本用：若它不是一次齐次，按比例改货币单位会改「真实」投入；若它对 \\(w\\) 不凹，要素价格的平均会比平均成本更贵，与「同一 \\(z\\) 仍可行」矛盾。缺口是列出对偶清单，使后课看到一个 \\(c\\) 就能还原技术，而不必先信某个 \\(f\\) 的函数形式。</p><p>投入需求集 \\(V(q)=\\{z:f(z)\\ge q\\}\\)。则 \\(c(w,q)=\\inf\\{w\\cdot z:z\\in V(q)\\}\\)，即 \\(V(q)\\) 的支撑函数。支撑函数的性质不依赖 \\(f\\) 可微，列昂惕夫的角点也包括在内。</p><p><span class="marginnote">术语翻译：「支撑函数」可以直观成——从集合外面用一块平直的账单板去贴 \\(V(q)\\)，板的方向由价格 \\(w\\) 决定，贴到的那一点的账单金额就是 \\(c(w,q)\\)；换一个贴的角度（相对价格），就换一组最优投入。</span></p><h3 id="先性质-后引理" tabindex="-1">先性质，后引理 <a class="header-anchor" href="#先性质-后引理" aria-label="Permalink to &quot;先性质，后引理&quot;">​</a></h3><p>Shephard 说 \\(\\nabla_w c=z\\)。那是可微点上的包络，下一课专写。本课的齐次、单调、凹，在不可微时仍成立，而且它们约束着「什么样的导数（若存在）配得上一个 \\(c\\)」。把引理写在性质前面，会让人以为成本函数只有那一条导数公式。</p><p><span class="marginnote">一次齐次：\\(c(\\lambda w,q)=\\lambda c(w,q)\\)，\\(\\lambda\\gt 0\\)。最优 \\(z\\) 不变，只是账单乘 \\(\\lambda\\)。这也是「没有货币幻觉」：要素价格与成本同单位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从定义推，不猜函数形式。</p><ul><li>齐次：可行集不随 \\(\\lambda\\) 变，\\(w\\) 换成 \\(\\lambda w\\)，目标同倍。</li><li>非降：\\(\\tilde w\\ge w\\) 则同一 \\(z\\) 更贵，下确界不能更低。</li><li>凹于 \\(w\\)：对任意 \\(w,w&#39;\\) 与 \\(\\theta\\in[0,1]\\)，\\(c(\\theta w+(1-\\theta)w&#39;,q)\\ge\\theta c(w,q)+(1-\\theta)c(w&#39;,q)\\) 的方向其实是凹——支撑函数对价格是凹的：平均价格下的最优投入按原来任一组价格计账都不低于该价格的最优成本，两笔加权恰为平均价格下的账单，故 \\(c\\) 凹。</li><li>对 \\(q\\) 非降：\\(V(q)\\) 随 \\(q\\) 缩小（自由处置下）。</li><li><a href="/econ/homothetic-production">一次齐次 \\(f\\)</a>：\\(c(w,q)=q\\,c(w,1)\\)。技术凸（\\(f\\) 凹）时 \\(c\\) 对 \\(q\\) 凸。</li></ul><p>连续：在 \\(w\\gg 0\\) 上，非空闭 \\(V(q)\\) 给出有限 \\(c\\)；\\(w\\) 碰到轴时可能爆炸或要允许 \\(+\\infty\\)。</p><p><span class="marginnote">数字实例：一次齐次说要素价格全翻倍、成本恰好翻倍。原来用 2 单位劳动（单价 10 元）加 1 单位资本（单价 20 元），账单 40 元；价格全乘 2 后最优投入不变，账单 \\(2\\times20+1\\times40=80=2\\times40\\)。</span></p>',15)),(E(),l(s,null,{default:e(()=>[r(o,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIN%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9Ac%20%3D%20min%20w%C2%B7z%22%5D%20--%3E%20SUP%5B%22c%20%E6%98%AF%20V(q)%20%E7%9A%84%E6%94%AF%E6%92%91%22%5D%0A%20%20SUP%20--%3E%20HOM%5B%22%E4%B8%80%E6%AC%A1%E9%BD%90%E6%AC%A1%E4%BA%8E%20w%22%5D%0A%20%20SUP%20--%3E%20CONC%5B%22%E5%87%B9%E4%BA%8E%20w%E3%80%81%E9%9D%9E%E9%99%8D%22%5D%0A%20%20SUP%20--%3E%20Q%5B%22%E5%AF%B9%20q%20%E9%9D%9E%E9%99%8D%EF%BC%9BCRS%20%E5%88%99%E7%BA%BF%E6%80%A7%22%5D%0A%20%20CONC%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%8F%AF%E5%BE%AE%E7%82%B9%E4%B8%8A%E7%9A%84%20Shephard%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"本课不选 \\(q\\)，也不引入产品价格 \\(p\\)。利润函数的齐次与凸是平行清单，留给供给课。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"凹的机制是点态极小：每个固定 \\(z\\) 给出线性账单 \\(w\\cdot z\\)，\\(c\\) 是它们的下包络，故对 \\(w\\) 凹（\\(c(\\theta w+(1-\\theta)w')\\ge\\theta c(w)+(1-\\theta)c(w')\\)）。无替代时 \\(z\\) 钉死，\\(c\\) 对 \\(w\\) 线性；能替代时一种要素变贵就换掉，成本上升慢于线性。不要用「平均两套投入」去证凹——混合可行计划管的是 \\(c\\) 对 \\(q\\) 凸。",-1)),(E(),l(s,null,{default:e(()=>[r(o,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20LR%0A%20%20Z%5B%22%E6%AF%8F%E4%B8%AA%E5%9B%BA%E5%AE%9A%20z%EF%BC%9A%E8%B4%A6%E5%8D%95%20w%C2%B7z%20%E6%98%AF%E4%BB%B7%E6%A0%BC%E7%9A%84%E7%BA%BF%E6%80%A7%E5%87%BD%E6%95%B0%22%5D%20--%3E%20C%5B%22c(w%2Cq)%20%3D%20%E6%89%80%E6%9C%89%E7%BA%BF%E6%80%A7%E8%B4%A6%E5%8D%95%E7%9A%84%E4%B8%8B%E5%8C%85%E7%BB%9C%22%5D%0A%20%20C%20--%3E%20CONC%5B%22%E4%B8%8B%E5%8C%85%E7%BB%9C%20%E2%87%92%20c%20%E5%AF%B9%20w%20%E5%87%B9%22%5D%0A%20%20CONC%20--%3E%20SUB%5B%22%E8%83%BD%E6%9B%BF%E4%BB%A3%EF%BC%9A%E8%A6%81%E7%B4%A0%E5%8F%98%E8%B4%B5%E5%B0%B1%E6%8D%A2%E6%8E%89%EF%BC%8C%E6%88%90%E6%9C%AC%E5%8D%87%E5%BE%97%E6%85%A2%22%5D%0A%20%20CONC%20--%3E%20FIX%5B%22%E6%97%A0%E6%9B%BF%E4%BB%A3%EF%BC%9Az%20%E9%92%89%E6%AD%BB%EF%BC%8Cc%20%E9%9A%8F%20w%20%E7%BA%BF%E6%80%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：初学者容易把「\\(c\\) 凹于 \\(w\\)」记成「成本随价格下降」。凹说的是涨幅递减、平均价格下的成本不低于平均成本；方向上 \\(c\\) 仍随 \\(w\\) 非降——凹与单调是两条独立性质。</span></p><p>齐次的机制是会计：没有相对价格以外的绝对尺度。CRS 把产量从 \\(V(q)\\) 里提出去，剩下单位等产量的支撑，于是 MC 不随 \\(q\\) 变——上一课已经用过这句，本课把它认作 \\(c\\) 的性质而不是 \\(f\\) 的再计算。</p><p><span class="marginnote">凹加一次齐次，意味着 \\(c\\) 对 \\(w\\) 的超梯度（条件需求）本身零次齐次，且满足负半定的替代矩阵——那是下一课导数存在之后的可积条件，本课只把凹钉住。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>要素配额、不可逆投入，使当期 \\(V(q)\\) 不再是技术课那个静态集，\\(c\\) 对某些 \\(w\\) 的导数会「卡住」。联合产出时 \\(q\\) 是向量，支撑对 \\(w\\) 的性质不变，对 \\(q\\) 的单调变成对产出价格的对偶。整数投入让 \\(c\\) 对 \\(q\\) 跳。</p><p>也不要把账本上的历史成本当成 \\(c(w,q)\\)：支撑函数永远是当期 \\(w\\) 的前瞻最小值。</p><p>后课默认：\\(c(\\cdot,q)\\) 是 \\(V(q)\\) 的支撑，对 \\(w\\) 一次齐次、非降、凹；CRS 时对 \\(q\\) 线性。可微点上的导数等式下一课再写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>成本函数是投入需求集的支撑，性质来自线性目标加可行集，不来自猜 \\(f\\)。</li><li>对 \\(w\\)：一次齐次、非降、凹；对 \\(q\\) 非降；CRS 则 \\(c=q\\,c(w,1)\\)。</li><li>这些在 Shephard 之前成立，折拐技术也包括。</li><li>下一课在可微点把 \\(\\nabla_w c\\) 读成条件需求。</li><li>出处：Varian, <em>Microeconomic Analysis</em>；McFadden, 1978。</li></ul>',9))])}const D=c(d,[["render",A]]);export{u as __pageData,D as default};
